// This owner interface uses the existing, permission-checked workspace API.
let plannerOffset=0,plannerMode='week',plannerKind='all',taskPerson='',taskClient='',taskPriority='',taskSort='priority',clientQuery='',clientStatus='',activityEntity='';
const selectedTasks=new Set();
const TASK_STATES=['Open','In progress','Blocked','Done'];
