function applyClientFilters(){if(page!=='clients')return;let count=0;for(const card of document.querySelectorAll('.client-cards article')){const id=card.querySelector('[data-action="client-overview"]')?.dataset.id,c=store.clients.find(c=>c.id===id);card.hidden=!!c&&((clientStatus&&c.status!==clientStatus)||(clientQuery&&![c.name,c.contact,c.email,c.services].join(' ').toLowerCase().includes(clientQuery.toLowerCase())));if(!card.hidden)count++;}const grid=$('.client-cards');if(grid&&!count)grid.insertAdjacentHTML('beforeend','<p class="notice">No clients match these filters.</p>');}
const oldAttention=attentionItems;
attentionItems=function(){return [...all('tasks').filter(t=>t.status!=='Done'&&(due(t.due)||t.status==='Blocked')).map(t=>({title:t.title,text:`${t.status==='Blocked'?'Blocked':'Task overdue'} · ${taskOwner(t)} · ${bname(t.business_id)}`,page:'tasks',entity:'tasks',id:t.id,kind:'tasks'})),...oldAttention()];};
businessHealth=function(b){return store.tasks.some(t=>t.business_id===b.id&&t.status!=='Done'&&(due(t.due)||t.status==='Blocked'))||store.projects.some(p=>p.business_id===b.id&&p.status!=='Done'&&due(p.due))||store.invoices.some(i=>i.business_id===b.id&&balance(i)>0&&due(i.due))?'Needs attention':store.content.some(c=>c.business_id===b.id&&c.status==='In review')?'Review pending':'On track';};
function teamLoad(){return (store.people||[]).filter(p=>p.status==='Active'&&(!scope||(store.business_people||[]).some(m=>m.person_id===p.id&&m.business_id===scope&&m.status==='Active'))).map(p=>{const tasks=all('tasks').filter(t=>t.assignee_id===p.id&&t.status!=='Done');return `<div class="list-row"><span class="avatar">${esc(initials(p.name))}</span><div class="grow"><strong>${esc(p.name)}</strong><p>${tasks.length} open · ${tasks.filter(t=>due(t.due)).length} overdue · ${tasks.filter(t=>t.status==='Blocked').length} blocked</p></div>${btn('View work','team-tasks',`data-person="${esc(p.id)}"`,'secondary compact')}</div>`;}).join('')||empty('Bring your team into GROW','Add people to a business and assign their next action.',navbtn('People & links','connections'));}
homePage=function(){const tasks=myTasks().filter(t=>t.status!=='Done').sort(taskRank),own=tasks.filter(t=>!t.assignee_id),agenda=agendaItems().filter(a=>a.date>=today()&&a.date<=addDays(today(),7)),ts=ledger();return heading(`Welcome back, ${store.settings.owner||'Jubayer'}.`,`${fullDate(today())} · ${scope?bname(scope):'Your businesses. Your next moves.'}`,`${btn('+ Quick task','quick-capture','','primary')}${addbtn('content','New content')}`)+`<div class="desk-shortcuts">${[['planner','Plan my week','today'],['tasks','Move work forward','tasks'],['connections','People & links','clients'],['content','Content → Social','content']].map(([p,label,ic])=>`<button data-action="navigate" data-page="${p}">${icon(ic)}<span>${label}</span>${icon('chevron')}</button>`).join('')}</div><div class="stats">${stat('My open work',own.length,`${own.filter(t=>t.due&&t.due<=today()).length} due today or overdue`,'tasks',true)}${stat('Needs a decision',attentionItems().length,'Blocked work and overdue records','alert')}${stat('Content to review',reviewItems().length,'Approve before Social handoff','content')}${stat('Outstanding',money(total(openInvoices().map(i=>({amount:balance(i)})))),'Recorded invoice balances','finance')}</div><div class="grid"><div class="stack">${card('My next actions',taskRows(own.slice(0,5)),btn('My task board','my-task-board','','secondary compact'))}${card('Decision inbox',attentionRows(6),navbtn('Today','today','secondary compact'))}${card('Business portfolio',portfolio(),navbtn('All businesses','businesses','secondary compact'))}</div><div class="stack">${card('Coming up this week',agenda.slice(0,7).map(agendaRow).join('')||'<p class="card-body muted">Add due dates to see your week here.</p>',navbtn('Open planner','planner','secondary compact'))}${card('Approval inbox',approvalRows(3),btn('Review content','content-approvals','','secondary compact'))}${card('Team workload',teamLoad(),navbtn('Manage people','connections','secondary compact'))}${card('Monthly cash',`<div class="card-body"><dl class="key-value"><div><dt>Received</dt><dd>${money(income(ts))}</dd></div><div><dt>Spent</dt><dd>${money(expenses(ts))}</dd></div><div><dt>Net recorded cash flow</dt><dd>${money(income(ts)-expenses(ts))}</dd></div></dl></div>`,navbtn('Finance','finance','secondary compact'))}</div></div><div class="three-column section-gap">${[['artbit','Artbit · client delivery','Clients, monthly plans, content, campaigns and reports'],['merch','Biggan PiC · merchandise','Design, printing, stock and order fulfillment'],['qfs','QFS · lead collection','Research, verification, follow-ups and the next action']].map(([p,title,text])=>card(title,`<div class="card-body"><p class="muted small">${text}</p><div class="section-gap">${navbtn('Open business',p)}</div></div>`)).join('')}</div>`;};
function activityPage(){const items=(store.activity||[]).filter(a=>(!activityEntity||a.entity===activityEntity)&&(!scope||(store[a.entity]||[]).some(r=>r.id===a.record_id&&(r.business_id===scope||(a.entity==='businesses'&&r.id===scope)))));return heading('What changed in your workspace.','The latest 60 recorded workspace events. Deleted or unlinked records may no longer open.',btn('Refresh','workspace-refresh','','secondary'))+`<div class="toolbar"><select id="activity-entity" aria-label="Activity record type">${option('','All record types',activityEntity)}${[...new Set((store.activity||[]).map(a=>a.entity))].map(e=>option(e,configs[e]?.title||e,activityEntity)).join('')}</select><span class="muted small">${items.length} events${scope?' · '+esc(bname(scope)):''}</span></div>${card('Recent activity',items.map(a=>{const r=(store[a.entity]||[]).find(r=>r.id===a.record_id);return `<div class="list-row"><span class="activity-marker">${icon(entityPage[a.entity]||'clock')}</span><div class="grow"><strong>${esc(a.action)} · ${esc(configs[a.entity]?.title||a.entity)}</strong><p>${esc(a.detail)}</p><small class="muted">${esc(new Date(a.at).toLocaleString('en-GB',{timeZone:'Asia/Dhaka'}))}</small></div>${r&&configs[a.entity]?btn('Open','agenda-open',`data-entity="${esc(a.entity)}" data-id="${esc(a.record_id)}"`,'secondary compact'):''}</div>`;}).join('')||'<p class="card-body muted">No recorded activity in this view.</p>')}`;}
const oldLocalBrief=localBrief;
localBrief=function(query='today'){if(/task/.test(query.toLowerCase()))return `YOUR WORK\n${myTasks().filter(t=>t.status!=='Done').length} native GROW tasks are open.\n${myTasks().filter(t=>t.status==='Blocked').length} are blocked.\n${myTasks().filter(t=>t.status!=='Done'&&due(t.due)).length} are overdue.\n\nNEXT ACTIONS\n${myTasks().filter(t=>t.status!=='Done').sort(taskRank).slice(0,8).map(t=>'- '+t.title+' · '+taskOwner(t)+' · '+shortDate(t.due)).join('\n')||'No open tasks yet.'}\n\nBrief based on saved records.${sampleCount()?' Sample records are included.':''}`;return oldLocalBrief(query);};
const oldSettingsPage=settingsPage;
settingsPage=function(){return oldSettingsPage().replace('AI, publishing and website feeds','Social publishing').replace('<dd>Not connected</dd></div></dl>','<dd>Connected to social.iamjubayer.com</dd></div></dl>').replace('AI and publishing services are not connected.','Approved content can be handed to Social. Facebook Pages support publishing on your command; other networks support draft handoff. Live AI and website feeds are not connected.');};
const oldAiPage=aiPage;
aiPage=function(){return oldAiPage().replace('finance or imported tasks','finance or your GROW tasks');};
showSearch=function(query){const q=query.trim().toLowerCase(),results=[];if(!q){$('#search-results').innerHTML=`<p class="muted small">Find a task, person, client, business, invoice or note.</p><div class="quick-prompts">${btn('+ Quick task','quick-capture','','primary')}${navbtn('Planner','planner')}${navbtn('People & links','connections')}</div>`;return;}for(const entity of Object.keys(entityPage))for(const r of store[entity]||[]){const title=r.title||r.name;if(title&&[title,r.notes,r.email,r.copy,r.contact,r.assignee_id?taskOwner(r):'',r.business_id?bname(r.business_id):''].join(' ').toLowerCase().includes(q))results.push({entity,r,title});}$('#search-results').innerHTML=results.slice(0,40).map(({entity,r,title})=>`<button class="search-result" data-action="agenda-open" data-entity="${esc(entity)}" data-id="${esc(r.id)}">${icon(entityPage[entity])}<div><strong>${esc(title)}</strong><small>${esc(configs[entity]?.title||entity)} · ${esc(r.business_id?bname(r.business_id):'Workspace')}</small></div></button>`).join('')||'<p class="muted small">No matching records.</p>';};
const oldSearchDialog=searchDialog;
searchDialog=function(){oldSearchDialog();showSearch('');};
const oldRender=render;
render=function(){oldRender();applyClientFilters();const actions=$('.topbar-right');if(actions)actions.insertAdjacentHTML('afterbegin',btn('+','quick-capture','aria-label="Quick task · Q" title="Quick task · Q"','primary compact'));};
// Navigation preferences contain only IDs, never credentials or workspace records.
function saveDeskView(){try{localStorage.setItem('grow-desk-view',JSON.stringify({scope,taskView,taskFilter,taskPerson,taskPriority,taskSort,plannerMode,plannerKind}));}catch{}}
const renderDesk=render;
render=function(){renderDesk();saveDeskView();};
async function moveTask(id,status){const t=found('tasks',id);if(!t||t.origin==='Imported')throw new Error('Imported tasks cannot be moved.');if(!TASK_STATES.includes(status))throw new Error('Choose a valid task stage.');if(t.status===status)return;await api('tasks/'+id,'PATCH',{status});}
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag-task]');if(!card)return;if(e.target.closest('button,input,select,a')){e.preventDefault();return;}e.dataTransfer.setData('text/x-grow-task',card.dataset.dragTask);e.dataTransfer.effectAllowed='move';card.classList.add('dragging');});
document.addEventListener('dragend',()=>{for(const el of document.querySelectorAll('.dragging,.drop-active'))el.classList.remove('dragging','drop-active');});
document.addEventListener('dragover',e=>{const col=e.target.closest('[data-drop-status]');if(col&&Array.from(e.dataTransfer.types).includes('text/x-grow-task')){e.preventDefault();e.dataTransfer.dropEffect='move';col.classList.add('drop-active');}});
document.addEventListener('dragleave',e=>{const col=e.target.closest('[data-drop-status]');if(col&&!col.contains(e.relatedTarget))col.classList.remove('drop-active');});
document.addEventListener('drop',async e=>{const col=e.target.closest('[data-drop-status]');if(!col)return;const id=e.dataTransfer.getData('text/x-grow-task');if(!id)return;e.preventDefault();col.classList.remove('drop-active');try{await moveTask(id,col.dataset.dropStatus);await refresh();render();toast('Task moved.');}catch(error){toast(error.message,true);}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;if(!['quick-capture','tasks-reset','planner-shift','planner-today','agenda-open','client-overview','client-new','team-tasks','my-task-board','task-reschedule','workspace-refresh'].includes(a))return;el.disabled=true;try{if(a==='quick-capture')quickCapture(el.dataset.date||today());if(a==='tasks-reset'){taskQuery='';taskPerson='';taskClient='';taskPriority='';taskFilter='all';taskSort='priority';selectedTasks.clear();render();}if(a==='planner-shift'){plannerOffset+=Number(el.dataset.days);render();}if(a==='planner-today'){plannerOffset=0;render();}if(a==='client-overview')clientOverview(el.dataset.id);if(a==='client-new'){const c=found('clients',el.dataset.client);openEditor(el.dataset.entity,'',{business_id:c.business_id,client_id:c.id,...(el.dataset.entity==='tasks'?{origin:'GROW',status:'Open',priority:'Medium',recurrence:'None'}:{})});}if(a==='agenda-open'){const entity=el.dataset.entity,id=el.dataset.id;if(entity==='tasks')taskDetail(id);else if(entity==='clients')clientOverview(id);else if(configs[entity])openEditor(entity,id);}if(a==='team-tasks'||a==='my-task-board'){taskPerson=a==='team-tasks'?el.dataset.person:'owner';taskFilter='open';taskClient='';taskPriority='';taskQuery='';go('tasks');}if(a==='task-reschedule'){const t=found('tasks',el.dataset.id);if(t.origin==='Imported')throw new Error('Imported tasks cannot be rescheduled.');await api('tasks/'+t.id,'PATCH',{due:addDays(today(),Number(el.dataset.days))});await refresh();render();taskDetail(t.id);toast('Task rescheduled.');}if(a==='workspace-refresh'){await refresh();render();toast('Workspace refreshed.');}}catch(error){toast(error.message,true);}finally{if(el.isConnected)el.disabled=false;}});
document.addEventListener('change',async e=>{const el=e.target;const filters={'task-person':'person','task-client-filter':'client','task-priority':'priority','task-sort':'sort','planner-mode':'plannerMode','planner-kind':'plannerKind','client-status-filter':'clientStatus','activity-entity':'activityEntity'};if(filters[el.id]){if(el.id==='task-person')taskPerson=el.value;if(el.id==='task-client-filter')taskClient=el.value;if(el.id==='task-priority')taskPriority=el.value;if(el.id==='task-sort')taskSort=el.value;if(el.id==='planner-mode')plannerMode=el.value;if(el.id==='planner-kind')plannerKind=el.value;if(el.id==='client-status-filter')clientStatus=el.value;if(el.id==='activity-entity')activityEntity=el.value;render();}if(el.id==='scope'){taskPerson='';taskClient='';selectedTasks.clear();render();}if(el.id==='quick-business')updateQuickRefs();if(el.dataset.taskSelect){el.checked?selectedTasks.add(el.dataset.taskSelect):selectedTasks.delete(el.dataset.taskSelect);render();}if(el.id==='task-select-all'){for(const t of visibleTasks().filter(t=>t.origin!=='Imported'))el.checked?selectedTasks.add(t.id):selectedTasks.delete(t.id);render();}if(el.dataset.taskMove){el.disabled=true;const taskId=el.dataset.taskMove,clientId=$('#editor .client-overview')?.dataset.clientId;try{await moveTask(taskId,el.value);await refresh();render();if($('#editor').open){if(clientId)clientOverview(clientId);else taskDetail(taskId);}toast('Task updated.');}catch(error){el.value=found('tasks',taskId).status;toast(error.message,true);}finally{el.disabled=false;}}if(el.id==='task-bulk-status'&&el.value){const status=el.value,ids=[...selectedTasks];if(!ids.length){el.value='';return toast('Select at least one task.',true);}el.disabled=true;let changed=0;try{for(const id of ids){await moveTask(id,status);changed++;selectedTasks.delete(id);}await refresh();render();toast(`${changed} tasks moved to ${status}.`);}catch(error){await refresh();render();toast(`${changed} of ${ids.length} tasks updated. ${error.message}`,true);}finally{el.disabled=false;}}});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id==='quick-task-form'){e.preventDefault();const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));await api('tasks','POST',{...data,title:data.title.trim(),status:'Open',origin:'GROW',owner:data.assignee_id?(store.people.find(p=>p.id===data.assignee_id)?.name||''):store.settings.owner,category:data.business_id?'Other':'Personal'});await refresh();$('#editor').close();render();toast('Task created.');}catch(error){formError(error);}finally{button.disabled=false;}}if(form.id==='client-search-form'){e.preventDefault();clientQuery=String(new FormData(form).get('q')||'').trim();render();}});
document.addEventListener('keydown',e=>{if(e.defaultPrevented||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select,[contenteditable="true"]')||$('#editor').open)return;if(e.key.toLowerCase()==='q'){e.preventDefault();quickCapture();}if(e.key.toLowerCase()==='p'){e.preventDefault();go('planner');}});
async function bootDesk(){try{const saved=JSON.parse(localStorage.getItem('grow-desk-view')||'{}');await refresh();scope=store.businesses.some(b=>b.id===saved.scope)?saved.scope:'';taskView=['board','list'].includes(saved.taskView)?saved.taskView:'board';taskFilter=['all','open','today','overdue','personal'].includes(saved.taskFilter)?saved.taskFilter:'all';taskPerson=saved.taskPerson==='owner'||store.people.some(p=>p.id===saved.taskPerson)?saved.taskPerson:'';taskPriority=['High','Medium','Low'].includes(saved.taskPriority)?saved.taskPriority:'';taskSort=saved.taskSort==='due'?'due':'priority';plannerMode=saved.plannerMode==='day'?'day':'week';plannerKind=['tasks','content','projects','leads','invoices','resources','orders','website_work','productions'].includes(saved.plannerKind)?saved.plannerKind:'all';}catch{/* Private browsing can disable localStorage; the normal boot remains available. */}await boot();}
bootDesk();
